// TestDestroyerStub checks the methods, the constructors and the options
// of the double DestroyerStub.
func TestDestroyerStub(t *testing.T) {
	t.Parallel()

	t.Run("Destroy", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Destroy", destroyerStubDestroySubject)
	})

	t.Run("KeyID", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "KeyID", destroyerStubKeyIDSubject)
	})

	t.Run("Wrap", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Wrap", destroyerStubWrapSubject)
	})

	t.Run("Unwrap", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Unwrap", destroyerStubUnwrapSubject)
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()

		t.Run("Destroy", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Destroy", destroyerStubDestroySubject)
		})

		t.Run("KeyID", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "KeyID", destroyerStubKeyIDSubject)
		})

		t.Run("Wrap", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Wrap", destroyerStubWrapSubject)
		})

		t.Run("Unwrap", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Unwrap", destroyerStubUnwrapSubject)
		})
	})

	t.Run("DestroyerStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) destroyerStubInstance {
			return destroyerStubInstanceOf(tb, cryptotest.NewDestroyerStub(tb, cryptotest.DestroyerStubStrict()))
		})
	})

	t.Run("DestroyerStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes Destroy to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewDestroyerStub(t)
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubDelegateTo(inner))
			_, _ = destroyerStubDestroy(t, s)
			inner.OnDestroy.AssertCalledOnce(t, "Destroy calls the implementation")
		})

		t.Run("fails Destroy with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Destroy-delegate")
			inner := cryptotest.NewDestroyerStub(t)
			inner.OnDestroy.Faults(want, 1)
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubDelegateTo(inner))
			_, r1 := destroyerStubDestroy(t, s)
			assert.ErrorIs(t, r1, want, "Destroy fails with the error of the implementation")
		})

		t.Run("passes KeyID to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewDestroyerStub(t)
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubDelegateTo(inner))
			_ = destroyerStubKeyID(t, s)
			inner.OnKeyID.AssertCalledOnce(t, "KeyID calls the implementation")
		})

		t.Run("passes Wrap to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewDestroyerStub(t)
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubDelegateTo(inner))
			_, _ = destroyerStubWrap(t, s)
			inner.OnWrap.AssertCalledOnce(t, "Wrap calls the implementation")
		})

		t.Run("fails Wrap with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Wrap-delegate")
			inner := cryptotest.NewDestroyerStub(t)
			inner.OnWrap.Faults(want, 1)
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubDelegateTo(inner))
			_, r1 := destroyerStubWrap(t, s)
			assert.ErrorIs(t, r1, want, "Wrap fails with the error of the implementation")
		})

		t.Run("passes Unwrap to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := cryptotest.NewDestroyerStub(t)
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubDelegateTo(inner))
			_, _ = destroyerStubUnwrap(t, s)
			inner.OnUnwrap.AssertCalledOnce(t, "Unwrap calls the implementation")
		})

		t.Run("fails Unwrap with the error of the implementation", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Unwrap-delegate")
			inner := cryptotest.NewDestroyerStub(t)
			inner.OnUnwrap.Faults(want, 1)
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubDelegateTo(inner))
			_, r1 := destroyerStubUnwrap(t, s)
			assert.ErrorIs(t, r1, want, "Unwrap fails with the error of the implementation")
		})
	})

	t.Run("DestroyerStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) destroyerStubInstance {
			return destroyerStubInstanceOf(tb, cryptotest.NewDestroyerStub(tb, cryptotest.DestroyerStubWithClock(clk)))
		})
	})

	t.Run("DestroyerStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) destroyerStubInstance {
			return destroyerStubInstanceOf(
				tb,
				cryptotest.NewDestroyerStub(tb, cryptotest.DestroyerStubWithRandSource(src)),
			)
		})
	})

	t.Run("DestroyerStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) destroyerStubInstance {
			return destroyerStubInstanceOf(tb, cryptotest.NewDestroyerStub(tb, cryptotest.DestroyerStubBenchMode()))
		})
	})

	t.Run("DestroyerStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) destroyerStubInstance {
			return destroyerStubInstanceOf(
				tb,
				cryptotest.NewDestroyerStub(
					tb,
					cryptotest.DestroyerStubWithClock(clk),
					cryptotest.DestroyerStubWithLatency(d),
				),
			)
		})
	})

	t.Run("DestroyerStubFailing", func(t *testing.T) {
		t.Parallel()

		t.Run("fails Destroy with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Destroy-failing")
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubFailing(want))
			_, r1 := destroyerStubDestroy(t, s)
			assert.ErrorIs(t, r1, want, "Destroy fails with the error of DestroyerStubFailing")
		})

		t.Run("fails Wrap with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Wrap-failing")
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubFailing(want))
			_, r1 := destroyerStubWrap(t, s)
			assert.ErrorIs(t, r1, want, "Wrap fails with the error of DestroyerStubFailing")
		})

		t.Run("fails Unwrap with its error", func(t *testing.T) {
			t.Parallel()
			want := errors.New("Unwrap-failing")
			s := cryptotest.NewDestroyerStub(t, cryptotest.DestroyerStubFailing(want))
			_, r1 := destroyerStubUnwrap(t, s)
			assert.ErrorIs(t, r1, want, "Unwrap fails with the error of DestroyerStubFailing")
		})
	})

	t.Run("WithDestroyerDestroy", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Destroy", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewDestroyerStub(
				t,
				cryptotest.WithDestroyerDestroy(func(_ context.Context, _ string) (time.Time, error) {
					called = true
					var z0 time.Time
					var z1 error
					return z0, z1
				}),
			)
			_, _ = destroyerStubDestroy(t, s)
			assert.True(t, called, "WithDestroyerDestroy sets the function of Destroy")
		})
	})

	t.Run("WithDestroyerKeyID", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of KeyID", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewDestroyerStub(t, cryptotest.WithDestroyerKeyID(func() string {
				called = true
				var z0 string
				return z0
			}))
			_ = destroyerStubKeyID(t, s)
			assert.True(t, called, "WithDestroyerKeyID sets the function of KeyID")
		})
	})

	t.Run("WithDestroyerWrap", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Wrap", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewDestroyerStub(
				t,
				cryptotest.WithDestroyerWrap(func(_ context.Context, _ []byte) ([]byte, error) {
					called = true
					var z0 []byte
					var z1 error
					return z0, z1
				}),
			)
			_, _ = destroyerStubWrap(t, s)
			assert.True(t, called, "WithDestroyerWrap sets the function of Wrap")
		})
	})

	t.Run("WithDestroyerUnwrap", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Unwrap", func(t *testing.T) {
			t.Parallel()
			called := false
			s := cryptotest.NewDestroyerStub(
				t,
				cryptotest.WithDestroyerUnwrap(func(_ context.Context, _ []byte) ([]byte, error) {
					called = true
					var z0 []byte
					var z1 error
					return z0, z1
				}),
			)
			_, _ = destroyerStubUnwrap(t, s)
			assert.True(t, called, "WithDestroyerUnwrap sets the function of Unwrap")
		})
	})
}

